438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 \\u0434\\u0438\\u0444\\u0444\\u0443\\u0437\\u043d\\u044b\\u0439 \\u0448\\u0443\\u043c: \\u0430\\u043b\\u0433\\u043e\\u0440\\u0438\\u0442\\u043c **\\u043d\\u0435 \\u0434\\u043e\\u043b\\u0436\\u0435\\u043d** \\u043e\\u0431\\u044a\\u0435\\u0434\\u0438\\u043d\\u044f\\u0442\\u044c \\u043d\\u0435\\u0441\\u0432\\u044f\\u0437\\u0430\\u043d\\u043d\\u044b\\u0435 \\u0448\\u0443\\u043c\\u043d\\u044b\\u0435 \\u0442\\u043e\\u0447\\u043a\\u0438 \\u0432 \\u0440\\u0435\\u0434\\u043a\\u0438\\u0439 \\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d.\\n  - \\u041f\\u0435\\u0440\\u0435\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043a\\u0430 \\u043f\\u0440\\u0438\\u0437\\u043d\\u0430\\u043a\\u043e\\u0432 (Feature Permutation Control): \\u0440\\u0430\\u0437\\u0440\\u0443\\u0448\\u0435\\u043d\\u0438\\u0435 \\u043c\\u0435\\u0436\\u043f\\u0440\\u0438\\u0437\\u043d\\u0430\\u043a\\u043e\\u0432\\u044b\\u0445 \\u043a\\u043e\\u0440\\u0440\\u0435\\u043b\\u044f\\u0446\\u0438\\u0439 \\u0432 \\u0440\\u0435\\u0434\\u043a\\u043e\\u0439 \\u0433\\u0440\\u0443\\u043f\\u043f\\u0435 \\u0434\\u043e\\u043b\\u0436\\u043d\\u043e \\u043f\\u0440\\u0438\\u0432\\u043e\\u0434\\u0438\\u0442\\u044c \\u043a \\u0438\\u0441\\u0447\\u0435\\u0437\\u043d\\u043e\\u0432\\u0435\\u043d\\u0438\\u044e \\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d\\u0430 \\u0438\\u0437 \\u0432\\u044b\\u0432\\u043e\\u0434\\u0430 Docta.\\n  - \\u0421\\u043b\\u0443\\u0447\\u0430\\u0439\\u043d\\u044b\\u0435 \\u043c\\u0435\\u0442\\u043a\\u0438 (Label Noise Control): \\u0434\\u043b\\u044f supervised-\\u0441\\u0446\\u0435\\u043d\\u0430\\u0440\\u0438\\u044f \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u043a\\u0430 \\u0442\\u043e\\u0433\\u043e, \\u0447\\u0442\\u043e Docta \\u043e\\u0442\\u043b\\u0438\\u0447\\u0430\\u0435\\u0442 \\u0441\\u043b\\u0443\\u0447\\u0430\\u0439\\u043d\\u044b\\u0435 \\u043e\\u0448\\u0438\\u0431\\u043a\\u0438 \\u0440\\u0430\\u0437\\u043c\\u0435\\u0442\\u043a\\u0438 \\u043e\\u0442 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u043d\\u044b\\u0445 \\u0440\\u0435\\u0434\\u043a\\u0438\\u0445 \\u043f\\u043e\\u0434\\u0433\\u0440\\u0443\\u043f\\u043f (minority slices).\\n\\n---\\n\\n## 3. \\u041f\\u043e\\u0448\\u0430\\u0433\\u043e\\u0432\\u044b\\u0439 \\u043f\\u0430\\u0439\\u043f\\u043b\\u0430\\u0439\\u043d Docta \\u0434\\u043b\\u044f \\u0442\\u0430\\u0431\\u043b\\u0438\\u0447\\u043d\\u044b\\u0445 \\u0434\\u0430\\u043d\\u043d\\u044b\\u0445\\n\\n\\u041f\\u0430\\u0439\\u043f\\u043b\\u0430\\u0439\\u043d \\u0440\\u0435\\u0430\\u043b\\u0438\\u0437\\u0443\\u0435\\u0442 \\u043a\\u0430\\u043a **Unsupervised**, \\u0442\\u0430\\u043a \\u0438 **Supervised** \\u0440\\u0435\\u0436\\u0438\\u043c\\u044b.\\n\\n```\\n       +-------------------------------------------------------------+\\n       |                  \\u0421\\u044b\\u0440\\u044b\\u0435 \\u0442\\u0430\\u0431\\u043b\\u0438\\u0447\\u043d\\u044b\\u0435 \\u0434\\u0430\\u043d\\u043d\\u044b\\u0435 X (\\u0438 Y)             |\\n       +-------------------------------------------------------------+\\n                                      |\\n                                      v\\n  [\\u0428\\u0430\\u0433 1] \\u041f\\u0440\\u0435\\u0434\\u043e\\u0431\\u0440\\u0430\\u0431\\u043e\\u0442\\u043a\\u0430 \\u0438 \\u0442\\u0430\\u0431\\u043b\\u0438\\u0447\\u043d\\u043e\\u0435 \\u043f\\u0440\\u0435\\u0434\\u0441\\u0442\\u0430\\u0432\\u043b\\u0435\\u043d\\u0438\\u0435 (Latent Embeddings)\\n          - \\u0426\\u0435\\u043b\\u0435\\u0432\\u043e\\u0435/\\u043a\\u0432\\u0430\\u043d\\u0442\\u0438\\u043b\\u044c\\u043d\\u043e\\u0435 \\u043a\\u043e\\u0434\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435, Robust Scaling\\n          - \\u041e\\u0431\\u0443\\u0447\\u0435\\u043d\\u0438\\u0435 \\u0442\\u0430\\u0431\\u043b\\u0438\\u0447\\u043d\\u043e\\u0433\\u043e \\u044d\\u043d\\u043a\\u043e\\u0434\\u0435\\u0440\\u0430 (GBDT Leaf Embedding / FT-Transformer)\\n                                      |\\n                                      v\\n  [\\u0428\\u0430\\u0433 2] \\u0410\\u043d\\u0430\\u043b\\u0438\\u0437 \\u043f\\u043b\\u043e\\u0442\\u043d\\u043e\\u0441\\u0442\\u0438 \\u0438 \\u043a\\u043e\\u0433\\u0435\\u0440\\u0435\\u043d\\u0442\\u043d\\u043e\\u0441\\u0442\\u0438 \\u0432 Docta (Scoring)\\n          - Global Density Score: g(x) via k-NN / KDE\\n          - Local Coherence Score: c(x) via graph connectivity / mutual k-NN\\n                                      |\\n                                      v\\n  [\\u0428\\u0430\\u0433 3] \\u0424\\u0438\\u043b\\u044c\\u0442\\u0440\\u0430\\u0446\\u0438\\u044f \\u0448\\u0443\\u043c\\u0430 \\u0438 \\u043a\\u043b\\u0430\\u0441\\u0441\\u0438\\u0444\\u0438\\u043a\\u0430\\u0446\\u0438\\u044f \\u043e\\u0431\\u044a\\u0435\\u043a\\u0442\\u043e\\u0432\\n          - g(x) \\u0432\\u044b\\u0441\\u043e\\u043a\\u043e\\u0435                -> Majority\\n          - g(x) \\u043d\\u0438\\u0437\\u043a\\u043e\\u0435, c(x) \\u043d\\u0438\\u0437\\u043a\\u043e\\u0435    -> Noise / Isolated Outlier (\\u041e\\u0442\\u0441\\u0435\\u043a\\u0430\\u0435\\u0442\\u0441\\u044f)\\n          - g(x) \\u043d\\u0438\\u0437\\u043a\\u043e\\u0435, c(x) \\u0432\\u044b\\u0441\\u043e\\u043a\\u043e\\u0435   -> RARE PATTERN CANDIDATE\\n                                      |\\n                                      v\\n  [\\u0428\\u0430\\u0433 4] Supervised Slice Alignment (\\u043f\\u0440\\u0438 \\u043d\\u0430\\u043b\\u0438\\u0447\\u0438\\u0438 Y)\\n          - \\u0410\\u043d\\u0430\\u043b\\u0438\\u0437 \\u043f\\u043e\\u0442\\u0435\\u0440\\u044c \\u0431\\u0430\\u0437\\u043e\\u0432\\u043e\\u0439 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438 L(f(x), y)\\n          - \\u0424\\u043e\\u0440\\u043c\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 Coherent Underperforming Slices (\\u0432\\u044b\\u0441\\u043e\\u043a\\u0438\\u0439 loss + \\u043e\\u0431\\u0449\\u0438\\u0435 \\u0444\\u0438\\u0447\\u0438)\\n                                      |\\n                                      v\\n  [\\u0428\\u0430\\u0433 5] \\u0413\\u0435\\u043d\\u0435\\u0440\\u0430\\u0446\\u0438\\u044f \\u0438\\u043d\\u0442\\u0435\\u0440\\u043f\\u0440\\u0435\\u0442\\u0438\\u0440\\u0443\\u0435\\u043c\\u044b\\u0445 \\u043f\\u0440\\u0430\\u0432\\u0438\\u043b (Surrogate Rule Extraction)\\n          - \\u0414\\u0435\\u0440\\u0435\\u0432\\u043e \\u0440\\u0435\\u0448\\u0435\\u043d\\u0438\\u0439 \\u0433\\u043b\\u0443\\u0431\\u0438\\u043d\\u044b 3-4 / \\u0430\\u0441\\u0441\\u043e\\u0446\\u0438\\u0430\\u0442\\u0438\\u0432\\u043d\\u044b\\u0435 \\u043f\\u0440\\u0430\\u0432\\u0438\\u043b\\u0430 \\u0434\\u043b\\u044f \\u043e\\u043f\\u0438\\u0441\\u0430\\u043d\\u0438\\u044f \\u0441\\u0440\\u0435\\u0437\\u0430\\n```\\n\\n### \\u0428\\u0430\\u0433 1: \\u0418\\u0437\\u0432\\u043b\\u0435\\u0447\\u0435\\u043d\\u0438\\u0435 \\u0442\\u0430\\u0431\\u043b\\u0438\\u0447\\u043d\\u044b\\u0445 \\u043f\\u0440\\u0435\\u0434\\u0441\\u0442\\u0430\\u0432\\u043b\\u0435\\u043d\\u0438\\u0439 (Embeddings)\\n1. \\u041a\\u0430\\u0442\\u0435\\u0433\\u043e\\u0440\\u0438\\u0430\\u043b\\u044c\\u043d\\u044b\\u0435 \\u043f\\u0440\\u0438\\u0437\\u043d\\u0430\\u043a\\u0438 \\u043a\\u043e\\u0434\\u0438\\u0440\\u0443\\u044e\\u0442\\u0441\\u044f \\u0447\\u0435\\u0440\\u0435\\u0437 Target Encoding (\\u0441 \\u0440\\u0435\\u0433\\u0443\\u043b\\u044f\\u0440\\u0438\\u0437\\u0430\\u0446\\u0438\\u0435\\u0439 out-of-fold) \\u0438\\u043b\\u0438 Entity Embeddings.\\n2. \\u041d\\u0435\\u043f\\u0440\\u0435\\u0440\\u044b\\u0432\\u043d\\u044b\\u0435 \\u043f\\u0440\\u0438\\u0437\\u043d\\u0430\\u043a\\u0438 \\u043c\\u0430\\u0441\\u0448\\u0442\\u0430\\u0431\\u0438\\u0440\\u0443\\u044e\\u0442\\u0441\\u044f \\u0447\\u0435\\u0440\\u0435\\u0437 \\u043a\\u0432\\u0430\\u043d\\u0442\\u0438\\u043b\\u044c\\u043d\\u044b\\u0435/\\u0440\\u043e\\u0431\\u0430\\u0441\\u0442\\u043d\\u044b\\u0435 \\u043f\\u0440\\u0435\\u043e\\u0431\\u0440\\u0430\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f.\\n3. \\u041e\\u0431\\u0443\\u0447\\u0430\\u0435\\u0442\\u0441\\u044f \\u0433\\u0440\\u0430\\u0434\\u0438\\u0435\\u043d\\u0442\\u043d\\u044b\\u0439 \\u0431\\u0443\\u0441\\u0442\\u0438\\u043d\\u0433 (LightGBM/CatBoost) \\u0438\\u043b\\u0438 \\u0430\\u0432\\u0442\\u043e\\u044d\\u043d\\u043a\\u043e\\u0434\\u0435\\u0440 (TabNet/FT-Transformer). \\u0412\\u0435\\u043a\\u0442\\u043e\\u0440 \\u043f\\u0440\\u0435\\u0434\\u0441\\u0442\\u0430\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f $z_i \\\\in \\\\mathbb{R}^d$ \\u0438\\u0437\\u0432\\u043b\\u0435\\u043a\\u0430\\u0435\\u0442\\u0441\\u044f \\u0438\\u0437 \\u0438\\u043d\\u0434\\u0435\\u043a\\u0441\\u043e\\u0432 \\u0430\\u043a\\u0442\\u0438\\u0432\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0445 \\u043b\\u0438\\u0441\\u0442\\u044c\\u0435\\u0432 \\u0434\\u0435\\u0440\\u0435\\u0432\\u044c\\u0435\\u0432 \\u0438\\u043b\\u0438 \\u043b\\u0430\\u0442\\u0435\\u043d\\u0442\\u043d\\u043e\\u0433\\u043e \\u0441\\u043b\\u043e\\u044f \\u043d\\u0435\\u0439\\u0440\\u043e\\u0441\\u0435\\u0442\\u0438, \\u0447\\u0442\\u043e \\u0433\\u0430\\u0440\\u0430\\u043d\\u0442\\u0438\\u0440\\u0443\\u0435\\u0442 \\u0443\\u0447\\u0435\\u0442 \\u0441\\u043b\\u043e\\u0436\\u043d\\u044b\\u0445 \\u043d\\u0435\\u043b\\u0438\\u043d\\u0435\\u0439\\u043d\\u044b\\u0445 \\u0432\\u0437\\u0430\\u0438\\u043c\\u043e\\u0434\\u0435\\u0439\\u0441\\u0442\\u0432\\u0438\\u0439 \\u043f\\u0440\\u0438\\u0437\\u043d\\u0430\\u043a\\u043e\\u0432.\\n\\n### \\u0428\\u0430\\u0433 2: \\u0421\\u043a\\u043e\\u0440\\u0438\\u043d\\u0433 \\u0440\\u0435\\u0434\\u043a\\u043e\\u0441\\u0442\\u0438 \\u0438 \\u0432\\u043d\\u0443\\u0442\\u0440\\u0435\\u043d\\u043d\\u0435\\u0439 \\u0441\\u0432\\u044f\\u0437\\u043d\\u043e\\u0441\\u0442\\u0438 (Docta Rarity & Coherence)\\n\\u0414\\u043b\\u044f \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u0442\\u043e\\u0447\\u043a\\u0438 $z_i$ \\u0432\\u044b\\u0447\\u0438\\u0441\\u043b\\u044f\\u044e\\u0442\\u0441\\u044f \\u0434\\u0432\\u0435 \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438:\\n1. **Global Rarity Score ($R_i$):** \\u0440\\u0430\\u0441\\u0441\\u0442\\u043e\\u044f\\u043d\\u0438\\u0435 \\u0434\\u043e $k$-\\u0433\\u043e \\u0431\\u043b\\u0438\\u0436\\u0430\\u0439\\u0448\\u0435\\u0433\\u043e \\u0441\\u043e\\u0441\\u0435\\u0434\\u0430 ($k_{large} \\\\approx 0.05 \\\\cdot N$) \\u0438\\u043b\\u0438 \\u043e\\u0431\\u0440\\u0430\\u0442\\u043d\\u0430\\u044f \\u044f\\u0434\\u0435\\u0440\\u043d\\u0430\\u044f \\u043f\\u043b\\u043e\\u0442\\u043d\\u043e\\u0441\\u0442\\u044c:\\n   $$R_i = \\\\frac{1}{k_{large}} \\\\sum_{j \\\\in \\\\mathcal{N}_{k_{large}}(i)} \\\\|z_i - z_j\\\\|_2$$\\n   \\u0412\\u044b\\u0441\\u043e\\u043a\\u043e\\u0435 \\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u0435 $R_i$ \\u0443\\u043a\\u0430\\u0437\\u044b\\u0432\\u0430\\u0435\\u0442 \\u043d\\u0430 \\u043f\\u0440\\u0438\\u043d\\u0430\\u0434\\u043b\\u0435\\u0436\\u043d\\u043e\\u0441\\u0442\\u044c \\u043a \\u043c\\u0430\\u043b\\u043e\\u0447\\u0438\\u0441\\u043b\\u0435\\u043d\\u043d\\u043e\\u0439 \\u043e\\u0431\\u043b\\u0430\\u0441\\u0442\\u0438.\\n2. **Local Coherence Score ($C_i$):** \\u043f\\u043b\\u043e\\u0442\\u043d\\u043e\\u0441\\u0442\\u044c \\u0432 \\u043c\\u0430\\u043b\\u043e\\u043c \\u0440\\u0430\\u0434\\u0438\\u0443\\u0441\\u0435 ($k_{small} \\\\approx 5..15$) \\u043f\\u043e \\u043e\\u0442\\u043d\\u043e\\u0448\\u0435\\u043d\\u0438\\u044e \\u043a \\u0432\\u0437\\u0430\\u0438\\u043c\\u043d\\u043e\\u043c\\u0443 \\u0433\\u0440\\u0430\\u0444\\u0443 k-\\u0431\\u043b\\u0438\\u0436\\u0430\\u0439\\u0448\\u0438\\u0445 \\u0441\\u043e\\u0441\\u0435\\u0434\\u0435\\u0439 (Mutual k-NN):\\n   $$C_i = \\\\frac{1}{|\\\\mathcal{N}_{k_{small}}(i)|} \\\\sum_{j \\\\in \\\\mathcal{N}_{k_{small}}(i)} \\\\mathbb{I}(i \\\\in \\\\mathcal{N}_{k_{small}}(j)) \\\\cdot \\\\exp\\\\left(-\\\\frac{\\\\|z_i - z_j\\\\|_2^2}{2\\\\sigma^2}\\\\right)$$\\n   \\u0412\\u044b\\u0441\\u043e\\u043a\\u043e\\u0435 \\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u0435 $C_i$ \\u043e\\u0437\\u043d\\u0430\\u0447\\u0430\\u0435\\u0442, \\u0447\\u0442\\u043e \\u0443 \\u0442\\u043e\\u0447\\u043a\\u0438 \\u0435\\u0441\\u0442\\u044c \\u0431\\u043b\\u0438\\u0437\\u043a\\u0438\\u0435 \\u0438 \\u0432\\u0437\\u0430\\u0438\\u043c\\u043d\\u043e \\u0441\\u043e\\u0433\\u043b\\u0430\\u0441\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0435 \\u0441\\u043e\\u0441\\u0435\\u0434\\u0438 (\\u043d\\u0430\\u043b\\u0438\\u0447\\u0438\\u0435 \\u043a\\u043b\\u0430\\u0441\\u0442\\u0435\\u0440\\u043d\\u043e\\u0439 \\u0441\\u0442\\u0440\\u0443\\u043a\\u0442\\u0443\\u0440\\u044b).\\n\\n### \\u0428\\u0430\\u0433 3: \\u0414\\u0438\\u0444\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446\\u0438\\u0430\\u0446\\u0438\\u044f \\u0438 \\u0444\\u0438\\u043b\\u044c\\u0442\\u0440\\u0430\\u0446\\u0438\\u044f \\u0448\\u0443\\u043c\\u0430\\n\\u0424\\u043e\\u0440\\u043c\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u043c\\u0430\\u0442\\u0440\\u0438\\u0446\\u0430 \\u043a\\u043b\\u0430\\u0441\\u0441\\u0438\\u0444\\u0438\\u043a\\u0430\\u0446\\u0438\\u0438:\\n* **\\u0418\\u0441\\u0442\\u0438\\u043d\\u043d\\u044b\\u0439 \\u0440\\u0435\\u0434\\u043a\\u0438\\u0439 \\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d:** $R_i \\\\ge \\\\tau_{rarity}$ \\u0418 $C_i \\\\ge \\\\tau_{coherence}$.\\n* **\\u0418\\u0437\\u043e\\u043b\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 \\u0448\\u0443\\u043c / \\u0432\\u044b\\u0431\\u0440\\u043e\\u0441:** $R_i \\\\ge \\\\tau_{rarity}$ \\u0418 $C_i < \\\\tau_{coherence}$.\\n* **\\u041c\\u0430\\u0436\\u043e\\u0440\\u0438\\u0442\\u0430\\u0440\\u043d\\u0430\\u044f \\u043d\\u043e\\u0440\\u043c\\u0430:** $R_i < \\\\tau_{rarity}$.\\n\\n\\u041f\\u043e\\u0440\\u043e\\u0433\\u043e\\u0432\\u044b\\u0435 \\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u044f $\\\\tau_{rarity}$ \\u0438 $\\\\tau_{coherence}$ \\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u044f\\u044e\\u0442\\u0441\\u044f \\u0447\\u0435\\u0440\\u0435\\u0437 \\u0430\\u0434\\u0430\\u043f\\u0442\\u0438\\u0432\\u043d\\u044b\\u0435 \\u043a\\u0432\\u04