1\\\\%, 5\\\\%]$).\\n* **Noise Rejection Rate (NRR):** \\u0434\\u043e\\u043b\\u044f \\u0442\\u043e\\u0447\\u0435\\u043a \\u0434\\u0438\\u0444\\u0444\\u0443\\u0437\\u043d\\u043e\\u0433\\u043e \\u0448\\u0443\\u043c\\u0430, \\u043a\\u043e\\u0440\\u0440\\u0435\\u043a\\u0442\\u043d\\u043e \\u043e\\u0442\\u0444\\u0438\\u043b\\u044c\\u0442\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0445 \\u043a\\u0430\\u043a \\u0448\\u0443\\u043c, \\u0430 \\u043d\\u0435 \\u0440\\u0435\\u0434\\u043a\\u0438\\u0439 \\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d:\\n  $$\\\\text{NRR} = \\\\frac{|\\\\text{\\u0428\\u0443\\u043c} \\\\cap \\\\text{\\u041e\\u0442\\u0444\\u0438\\u043b\\u044c\\u0442\\u0440\\u043e\\u0432\\u0430\\u043d\\u043e \\u043a\\u0430\\u043a \\u0432\\u044b\\u0431\\u0440\\u043e\\u0441}|}{|\\\\text{\\u0428\\u0443\\u043c}|}$$\\n* **Separability Score:** ROC-AUC \\u043a\\u043b\\u0430\\u0441\\u0441\\u0438\\u0444\\u0438\\u043a\\u0430\\u0442\\u043e\\u0440\\u0430, \\u0440\\u0430\\u0437\\u0434\\u0435\\u043b\\u044f\\u044e\\u0449\\u0435\\u0433\\u043e \\u0438\\u0441\\u0442\\u0438\\u043d\\u043d\\u044b\\u0435 \\u0440\\u0435\\u0434\\u043a\\u0438\\u0435 \\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d\\u044b \\u0438 \\u0434\\u0438\\u0444\\u0444\\u0443\\u0437\\u043d\\u044b\\u0439 \\u0448\\u0443\\u043c \\u043d\\u0430 \\u043e\\u0441\\u043d\\u043e\\u0432\\u0435 \\u0441\\u043a\\u043e\\u0440\\u043e\\u0432 Docta.\\n\\n### 5.2. \\u041c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438 \\u0441\\u0432\\u044f\\u0437\\u043d\\u043e\\u0441\\u0442\\u0438 \\u0438 \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0430 \\u043a\\u043b\\u0430\\u0441\\u0442\\u0435\\u0440\\u043e\\u0432\\n* **Cluster Silhouette Score** \\u0438 **Davies-Bouldin Index** \\u0434\\u043b\\u044f \\u043d\\u0430\\u0439\\u0434\\u0435\\u043d\\u043d\\u044b\\u0445 \\u0440\\u0435\\u0434\\u043a\\u0438\\u0445 \\u0433\\u0440\\u0443\\u043f\\u043f \\u0432 \\u043f\\u0440\\u043e\\u0441\\u0442\\u0440\\u0430\\u043d\\u0441\\u0442\\u0432\\u0435 \\u043f\\u0440\\u0435\\u0434\\u0441\\u0442\\u0430\\u0432\\u043b\\u0435\\u043d\\u0438\\u0439.\\n* **Intra-cluster Variance Ratio:** \\u043e\\u0442\\u043d\\u043e\\u0448\\u0435\\u043d\\u0438\\u0435 \\u0434\\u0438\\u0441\\u043f\\u0435\\u0440\\u0441\\u0438\\u0438 \\u0432\\u043d\\u0443\\u0442\\u0440\\u0438 \\u043d\\u0430\\u0439\\u0434\\u0435\\u043d\\u043d\\u043e\\u0433\\u043e \\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d\\u0430 \\u043a \\u0434\\u0438\\u0441\\u043f\\u0435\\u0440\\u0441\\u0438\\u0438 \\u0432\\u0441\\u0435\\u0439 \\u043f\\u043e\\u043f\\u0443\\u043b\\u044f\\u0446\\u0438\\u0438.\\n\\n### 5.3. \\u041c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438 \\u0438\\u043d\\u0442\\u0435\\u0440\\u043f\\u0440\\u0435\\u0442\\u0438\\u0440\\u0443\\u0435\\u043c\\u043e\\u0441\\u0442\\u0438\\n* **Fidelity & Complexity:** \\u0442\\u043e\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c \\u0441\\u0443\\u0440\\u0440\\u043e\\u0433\\u0430\\u0442\\u043d\\u043e\\u0433\\u043e \\u0434\\u0435\\u0440\\u0435\\u0432\\u0430 \\u0440\\u0435\\u0448\\u0435\\u043d\\u0438\\u0439 \\u043f\\u0440\\u0438 \\u043e\\u043f\\u0438\\u0441\\u0430\\u043d\\u0438\\u0438 \\u0440\\u0435\\u0434\\u043a\\u043e\\u0433\\u043e \\u0441\\u0440\\u0435\\u0437\\u0430 \\u0438 \\u0441\\u0440\\u0435\\u0434\\u043d\\u0435\\u0435 \\u0447\\u0438\\u0441\\u043b\\u043e \\u043f\\u0440\\u0435\\u0434\\u0438\\u043a\\u0430\\u0442\\u043e\\u0432 \\u0432 \\u043f\\u0440\\u0430\\u0432\\u0438\\u043b\\u0435 (\\u0446\\u0435\\u043b\\u0435\\u0432\\u043e\\u0439 \\u0434\\u0438\\u0430\\u043f\\u0430\\u0437\\u043e\\u043d: $\\\\le 4$ \\u0443\\u0441\\u043b\\u043e\\u0432\\u0438\\u0439).\\n\\n### 5.4. Downstream Utility (\\u041f\\u0440\\u0430\\u043a\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0430\\u044f \\u0446\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c)\\n\\u041e\\u0446\\u0435\\u043d\\u0438\\u0432\\u0430\\u0435\\u0442\\u0441\\u044f \\u0432\\u043b\\u0438\\u044f\\u043d\\u0438\\u0435 \\u043e\\u0431\\u043d\\u0430\\u0440\\u0443\\u0436\\u0435\\u043d\\u0438\\u044f \\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d\\u043e\\u0432 \\u043d\\u0430 \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u043e \\u043f\\u043e\\u0441\\u043b\\u0435\\u0434\\u0443\\u044e\\u0449\\u0435\\u0433\\u043e \\u043c\\u0430\\u0448\\u0438\\u043d\\u043d\\u043e\\u0433\\u043e \\u043e\\u0431\\u0443\\u0447\\u0435\\u043d\\u0438\\u044f:\\n1. **Worst-Group Accuracy / Recall:** \\u0442\\u043e\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438 \\u043d\\u0430 \\u0441\\u0430\\u043c\\u043e\\u043c \\u0441\\u043b\\u043e\\u0436\\u043d\\u043e\\u043c/\\u0440\\u0435\\u0434\\u043a\\u043e\\u043c \\u0441\\u0440\\u0435\\u0437\\u0435 \\u0434\\u043e \\u0438 \\u043f\\u043e\\u0441\\u043b\\u0435 \\u0442\\u0430\\u0440\\u0433\\u0435\\u0442\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0433\\u043e \\u043f\\u0435\\u0440\\u0435\\u0432\\u0437\\u0432\\u0435\\u0448\\u0438\\u0432\\u0430\\u043d\\u0438\\u044f \\u0434\\u0430\\u043d\\u043d\\u044b\\u0445 (sample reweighting) \\u0438\\u043b\\u0438 \\u0430\\u0443\\u0433\\u043c\\u0435\\u043d\\u0442\\u0430\\u0446\\u0438\\u0438 (targeted oversampling \\u043d\\u0430 \\u043e\\u0441\\u043d\\u043e\\u0432\\u0435 \\u043d\\u0430\\u0439\\u0434\\u0435\\u043d\\u043d\\u043e\\u0433\\u043e Docta \\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d\\u0430).\\n2. **Macro F1-Score:** \\u043e\\u0431\\u0449\\u0435\\u0435 \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u043e \\u043d\\u0430 \\u043d\\u0435\\u0441\\u0431\\u0430\\u043b\\u0430\\u043d\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u043c \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u0435 \\u0431\\u0435\\u0437 \\u0434\\u0435\\u0433\\u0440\\u0430\\u0434\\u0430\\u0446\\u0438\\u0438 \\u043c\\u0430\\u0436\\u043e\\u0440\\u0438\\u0442\\u0430\\u0440\\u043d\\u043e\\u0433\\u043e \\u043a\\u043b\\u0430\\u0441\\u0441\\u0430.\\n\\n---\\n\\n## 6. \\u041e\\u0446\\u0435\\u043d\\u043a\\u0430 \\u0440\\u0435\\u0430\\u043b\\u0438\\u0437\\u0443\\u0435\\u043c\\u043e\\u0441\\